package com.ironcompass.integration;

import com.ironcompass.route.LocationSpec;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;

public final class ShortestPathBridge
{
    private static final String NAMESPACE = "shortestpath";
    private static final String PATH = "path";
    private static final String CLEAR = "clear";
    private final EventBus eventBus;
    private final PluginManager pluginManager;

    @Inject
    public ShortestPathBridge(EventBus eventBus, PluginManager pluginManager)
    {
        this.eventBus = eventBus;
        this.pluginManager = pluginManager;
    }

    public void pathTo(LocationSpec location)
    {
        if (location == null)
        {
            return;
        }
        Map<String, Object> data = new HashMap<>();
        data.put("target", new WorldPoint(location.getX(), location.getY(), location.getPlane()));
        eventBus.post(new PluginMessage(NAMESPACE, PATH, data));
    }

    public void clear()
    {
        eventBus.post(new PluginMessage(NAMESPACE, CLEAR, Map.of()));
    }

    public IntegrationStatus status()
    {
        return IntegrationStatus.WORKING;
    }

    public boolean isAvailable()
    {
        for (Plugin plugin : pluginManager.getPlugins())
        {
            if ("Shortest Path".equals(plugin.getName()) && pluginManager.isPluginActive(plugin))
            {
                return true;
            }
        }
        return false;
    }
}

package com.ironcompass.integration;

import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import javax.inject.Inject;
import net.runelite.client.util.LinkBrowser;

public final class WikiBridge
{
    private static final String BASE_URL = "https://oldschool.runescape.wiki/w/";

    @Inject
    public WikiBridge()
    {
    }

    public void open(String page)
    {
        if (page == null || page.trim().isEmpty())
        {
            return;
        }
        LinkBrowser.browse(urlFor(page));
    }

    static String urlFor(String page)
    {
        String trimmed = page.trim();
        int fragmentIndex = trimmed.indexOf('#');
        String title = fragmentIndex < 0 ? trimmed : trimmed.substring(0, fragmentIndex);
        String fragment = fragmentIndex < 0 ? "" : trimmed.substring(fragmentIndex + 1);
        String url = BASE_URL + encode(title);
        return fragment.isEmpty() ? url : url + "#" + encode(fragment);
    }

    private static String encode(String value)
    {
        return URLEncoder.encode(value.replace(' ', '_'), StandardCharsets.UTF_8).replace("+", "%20");
    }

    public IntegrationStatus status()
    {
        return IntegrationStatus.WORKING;
    }
}

