            : GOAL_INSIGHTS.evaluate(newGoalPlan.getCatalog(), state, newGearProjection, newGoalPlan, persistence);
        updateGoalPickerButton();
        rebuildHome();
        rebuildBrowser();
        gearPanel.update(accountState, gearProjection);
