import com.ironcompass.goal.GoalCatalog;
import com.ironcompass.goal.GoalLoader;
import com.ironcompass.planner.GoalPlanProjection;
import com.ironcompass.planner.GoalPlannerService;
import com.ironcompass.planner.InMemoryPlannerPreferenceStore;
import com.ironcompass.planner.ProgressionRecommendationService;
import com.ironcompass.persistence.InMemoryManualOverrideStore;
import com.ironcompass.requirement.ConditionEvaluator;
import com.ironcompass.route.Route;
import com.ironcompass.route.RouteEvaluator;
import com.ironcompass.route.RouteLoader;
import com.ironcompass.route.RouteProjection;
import com.ironcompass.state.AccountMode;
import com.ironcompass.state.AccountState;
import com.ironcompass.state.BankSnapshot;
import com.ironcompass.supply.SupplyForecastService;
import com.ironcompass.training.IronmanMethodCatalog;
import com.ironcompass.training.IronmanMethodLoader;
import com.ironcompass.training.MethodPlannerService;
import java.util.Collections;
import java.util.Locale;
import org.junit.Test;

import static org.junit.Assert.assertTrue;

public class ProgressionPerformanceTest
{
    @Test
    public void fullProjectionStaysComfortablyBelowOneGameTick() throws Exception
    {
        Gson gson = new Gson();
        Route route = new RouteLoader(gson).loadResource("/routes/efficient-ironman.json");
        GearCatalog catalog = new GearLoader(gson).loadResource("/gear/ironman-gear-2026.json");
        GoalCatalog goalCatalog = new GoalLoader(gson).loadResource("/goals/ironman-goals-2026.json");
        IronmanMethodCatalog methodCatalog = new IronmanMethodLoader(gson)
            .loadResource("/methods/ironman-methods-2026.json");
        ConditionEvaluator conditions = new ConditionEvaluator();
        RouteEvaluator routes = new RouteEvaluator(conditions);
        GearRecommendationService gear = new GearRecommendationService(conditions);
        GoalDependencyResolver goals = new GoalDependencyResolver();
        SupplyForecastService supplies = new SupplyForecastService();
        GoalPlannerService planner = new GoalPlannerService(conditions, goals, supplies);
        ProgressionRecommendationService recommendations = new ProgressionRecommendationService();
        MethodPlannerService methods = new MethodPlannerService(conditions);
        InMemoryPlannerPreferenceStore plannerPreferences = new InMemoryPlannerPreferenceStore();
        InMemoryManualOverrideStore overrides = new InMemoryManualOverrideStore();
        InMemoryGearPreferenceStore preferences = new InMemoryGearPreferenceStore();
        preferences.setSelectedGoalId("gear.early.gloves");
        AccountState state = AccountState.builder().accountMode(AccountMode.IRONMAN)
            .skill("Attack", 70).skill("Strength", 70).skill("Defence", 70)
            .skill("Ranged", 75).skill("Magic", 75).skill("Prayer", 70)
            .bank(BankSnapshot.observed(Collections.emptyMap(), 1L)).build();

        for (int i = 0; i < 20; i++) evaluate(route, catalog, goalCatalog, methodCatalog, state, overrides,
            preferences, plannerPreferences, routes, gear, goals, supplies, planner, methods, recommendations);
        long total = 0L;
        long maximum = 0L;
        long routeTotal = 0L;
        long gearTotal = 0L;
        long goalTotal = 0L;
        long methodTotal = 0L;
        long recommendationTotal = 0L;
        long supplyTotal = 0L;
        int iterations = 200;
        for (int i = 0; i < iterations; i++)
        {
            long start = System.nanoTime();
            long stageStart = start;
            RouteProjection routeProjection = routes.evaluate(route, state, overrides, true, 4, 7);
            routeTotal += System.nanoTime() - stageStart;

            stageStart = System.nanoTime();
            GearProjection gearProjection = gear.evaluate(catalog, state, preferences, overrides);
            gearTotal += System.nanoTime() - stageStart;

            stageStart = System.nanoTime();
            goals.resolve(gearProjection, routeProjection);
            GoalPlanProjection goalPlan = planner.evaluate(goalCatalog, state, gearProjection, routeProjection,
                preferences);
            goalTotal += System.nanoTime() - stageStart;

            stageStart = System.nanoTime();
            goalPlan = goalPlan.withMethodRecommendation(methods.recommend(methodCatalog,
                goalPlan.getNextAction(), state, plannerPreferences, goalPlan.getActiveGoals()));
            methodTotal += System.nanoTime() - stageStart;

            stageStart = System.nanoTime();
            recommendations.evaluate(routeProjection, gearProjection, goalPlan, state, plannerPreferences);
            recommendationTotal += System.nanoTime() - stageStart;

            stageStart = System.nanoTime();
            supplies.evaluate(gearProjection.getSelected() == null
                ? gearProjection.getRecommended() : gearProjection.getSelected(), state);
            supplyTotal += System.nanoTime() - stageStart;
            long elapsed = System.nanoTime() - start;
            total += elapsed;
            maximum = Math.max(maximum, elapsed);
        }
        double averageMs = total / 1_000_000.0 / iterations;
        double maximumMs = maximum / 1_000_000.0;
        double routeMs = routeTotal / 1_000_000.0 / iterations;
        double gearMs = gearTotal / 1_000_000.0 / iterations;
        double goalMs = goalTotal / 1_000_000.0 / iterations;
        double methodMs = methodTotal / 1_000_000.0 / iterations;
        double recommendationMs = recommendationTotal / 1_000_000.0 / iterations;
        double supplyMs = supplyTotal / 1_000_000.0 / iterations;
        System.out.printf(Locale.ENGLISH,
            "Iron Compass full projection: avg %.3f ms, max %.3f ms; route %.3f ms; gear %.3f ms; "
                + "goal %.3f ms; methods %.3f ms; candidates/scoring %.3f ms; supplies %.3f ms; %d iterations%n",
            averageMs, maximumMs, routeMs, gearMs, goalMs, methodMs, recommendationMs, supplyMs, iterations);
        assertTrue("Average projection should stay under 50 ms, was " + averageMs, averageMs < 50.0);
        assertTrue("Maximum projection should stay under 250 ms, was " + maximumMs, maximumMs < 250.0);
        assertTrue("Average route projection should stay under 40 ms, was " + routeMs, routeMs < 40.0);
        assertTrue("Average Gear projection should stay under 30 ms, was " + gearMs, gearMs < 30.0);
        assertTrue("Average Goal projection should stay under 20 ms, was " + goalMs, goalMs < 20.0);
        assertTrue("Average method projection should stay under 20 ms, was " + methodMs, methodMs < 20.0);
        assertTrue("Average candidate generation/scoring should stay under 20 ms, was "
            + recommendationMs, recommendationMs < 20.0);
        assertTrue("Average supply projection should stay under 20 ms, was " + supplyMs, supplyMs < 20.0);
    }

    private static void evaluate(Route route, GearCatalog catalog, GoalCatalog goalsCatalog,
                                 IronmanMethodCatalog methodCatalog, AccountState state,
                                 InMemoryManualOverrideStore overrides, InMemoryGearPreferenceStore preferences,
                                 InMemoryPlannerPreferenceStore plannerPreferences,
                                 RouteEvaluator routes, GearRecommendationService gear,
                                 GoalDependencyResolver goals, SupplyForecastService supplies,
                                 GoalPlannerService planner, MethodPlannerService methods,
                                 ProgressionRecommendationService recommendations)
    {
        RouteProjection routeProjection = routes.evaluate(route, state, overrides, true, 4, 7);
        GearProjection gearProjection = gear.evaluate(catalog, state, preferences, overrides);
        goals.resolve(gearProjection, routeProjection);
        GoalPlanProjection goalPlan = planner.evaluate(goalsCatalog, state, gearProjection, routeProjection,
            preferences);
        goalPlan = goalPlan.withMethodRecommendation(methods.recommend(methodCatalog, goalPlan.getNextAction(),
            state, plannerPreferences, goalPlan.getActiveGoals()));
        recommendations.evaluate(routeProjection, gearProjection, goalPlan, state, plannerPreferences);
        supplies.evaluate(gearProjection.getSelected() == null
            ? gearProjection.getRecommended() : gearProjection.getSelected(), state);
    }
}

package com.ironcompass;

import java.awt.image.BufferedImage;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Properties;
import java.util.Set;
import java.util.stream.Collectors;
import javax.imageio.ImageIO;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import org.junit.Test;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public final class PublicationReadinessTest
{
    @Test
    public void pluginHubMetadataIsStandardAndMatchesDescriptor() throws Exception
    {
        Properties metadata = new Properties();
        try (InputStream input = Files.newInputStream(Paths.get("runelite-plugin.properties")))
        {
            metadata.load(input);
        }

        assertEquals("Iron Compass", metadata.getProperty("displayName"));
        assertEquals("com.ironcompass.IronCompassPlugin", metadata.getProperty("plugins"));
        assertEquals("standard", metadata.getProperty("build"));
        assertEquals("Gaby100amis", metadata.getProperty("author"));
        assertFalse("Public author metadata is required", blank(metadata.getProperty("author")));
        assertFalse("Replace generic contributor metadata before publication",
            metadata.getProperty("author").toLowerCase().contains("contributors"));
        assertTrue("Description should be useful in Plugin Hub search",
            metadata.getProperty("description", "").length() >= 40);
        assertFalse("Plugin Hub versions are commit-pinned; keep the optional version field absent",
            metadata.containsKey("version"));

        PluginDescriptor descriptor = IronCompassPlugin.class.getAnnotation(PluginDescriptor.class);
        assertNotNull(descriptor);
        assertEquals(metadata.getProperty("displayName"), descriptor.name());
        assertEquals(metadata.getProperty("description"), descriptor.description());
        assertArrayEquals(metadata.getProperty("tags").split(","), descriptor.tags());

        ConfigGroup configGroup = IronCompassConfig.class.getAnnotation(ConfigGroup.class);
        assertNotNull(configGroup);
        assertEquals("ironcompass", configGroup.value());

        Set<String> configKeys = Arrays.stream(IronCompassConfig.class.getDeclaredMethods())
            .map(method -> method.getAnnotation(ConfigItem.class))
            .filter(annotation -> annotation != null)
            .map(ConfigItem::keyName)
            .collect(Collectors.toSet());
        assertEquals(new HashSet<>(Arrays.asList(
            "preferSafeAlternatives", "wikiActions", "shortestPath",
            "completionNotifications", "preparationLookahead")), configKeys);

        Class<?> pluginClass = Class.forName(metadata.getProperty("plugins"));
        assertEquals(IronCompassPlugin.class, pluginClass);
        assertTrue(Plugin.class.isAssignableFrom(pluginClass));
    }

    @Test
    public void publicIconMeetsPluginHubLimitsAndMatchesBundledResource() throws Exception
    {
        Path publicIcon = Paths.get("icon.png");
        Path bundledIcon = Paths.get("src", "main", "resources", "icon.png");
        BufferedImage image = ImageIO.read(publicIcon.toFile());

        assertNotNull("Root icon must be a valid image", image);
        assertTrue("Plugin Hub icon width must be at most 48 px", image.getWidth() <= 48);
        assertTrue("Plugin Hub icon height must be at most 72 px", image.getHeight() <= 72);
        assertTrue("Root and bundled icons must stay identical",
            Arrays.equals(Files.readAllBytes(publicIcon), Files.readAllBytes(bundledIcon)));
    }

    @Test
    public void publicReleaseDocumentationExists()
    {
        for (String file : Arrays.asList("README.md", "LICENSE", "CHANGELOG.md", "CONTRIBUTING.md",
            "SECURITY.md", "THIRD_PARTY_NOTICES.md", "docs/PLUGIN_HUB_CHECKLIST.md",
            "docs/PLUGIN_HUB_SUBMISSION.md", "docs/GOAL_PLANNER.md"))
        {
            assertTrue("Missing public release document: " + file, Files.isRegularFile(Paths.get(file)));
        }
        assertFalse("Do not register a Plugin SPI service from an external plugin",
            Files.exists(Paths.get("src", "main", "resources", "META-INF", "services",
                "net.runelite.client.plugins.Plugin")));
    }

    @Test
    public void publicVersionComesFromOneReleaseProperty() throws Exception
    {
        Properties gradle = new Properties();
        try (InputStream input = Files.newInputStream(Paths.get("gradle.properties")))
        {
            gradle.load(input);
        }
        assertEquals("1.1.5",gradle.getProperty("pluginVersion"));
        assertEquals("1.1.5",IronCompassVersion.get());
        assertFalse(new String(Files.readAllBytes(Paths.get("runelite-plugin.properties")),
            java.nio.charset.StandardCharsets.UTF_8).contains("1.5.0"));
    }

    private static boolean blank(String value)
    {
        return value == null || value.trim().isEmpty();
    }
}

package com.ironcompass;

import com.google.gson.Gson;
import com.ironcompass.gear.GearCatalog;
import com.ironcompass.gear.GearLoader;
import com.ironcompass.gear.GearProjection;
import com.ironcompass.gear.GearRecommendationService;
import com.ironcompass.gear.GearStatus;
import com.ironcompass.gear.InMemoryGearPreferenceStore;
import com.ironcompass.persistence.InMemoryManualOverrideStore;
import com.ironcompass.persistence.ManualOverride;
import com.ironcompass.requirement.ConditionEvaluator;
import com.ironcompass.route.Route;
import com.ironcompass.route.RouteEvaluator;
import com.ironcompass.route.RouteJourney;
import com.ironcompass.route.RouteJourneyService;
import com.ironcompass.route.RouteLoader;
import com.ironcompass.route.RouteProjection;
import com.ironcompass.route.RouteSection;
import com.ironcompass.route.RouteStep;
import com.ironcompass.state.AccountMode;
import com.ironcompass.state.AccountState;
import com.ironcompass.state.BankSnapshot;
import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class SyntheticAccountProfilesTest
{
    @Test
    public void profilesAToEAlwaysReceivePositionActionAndGearDirection() throws Exception
    {
        Gson gson = new Gson();
        Route route = new RouteLoader(gson).loadResource("/routes/efficient-ironman.json");
        GearCatalog catalog = new GearLoader(gson).loadResource("/gear/ironman-gear-2026.json");
        ConditionEvaluator conditions = new ConditionEvaluator();
        int[] completedSteps = {0, 48, 150, 255, 330};
        int[] skillLevels = {1, 40, 60, 75, 90};

        for (int profile = 0; profile < completedSteps.length; profile++)
        {
            InMemoryManualOverrideStore overrides = new InMemoryManualOverrideStore();
            completeFirst(route, overrides, completedSteps[profile]);
            AccountState state = stateAt(skillLevels[profile], profile == 0
                ? BankSnapshot.unknown() : BankSnapshot.observed(Collections.emptyMap()));
            RouteProjection routeProjection = new RouteEvaluator(conditions).evaluate(route, state, overrides,
                true, 4, 7);
            GearProjection gearProjection = new GearRecommendationService(conditions).evaluate(catalog, state,
                new InMemoryGearPreferenceStore(), overrides);
            RouteJourney journey = new RouteJourneyService().project(routeProjection);

            assertNotNull("Profile " + (char) ('A' + profile) + " needs a next action", routeProjection.getCurrent());
            assertNotNull("Profile " + (char) ('A' + profile) + " needs a chapter", journey.getCurrent());
            if (profile == 0)
            {
                assertTrue("Unscanned profile A must expose unconfirmed ownership",
                    gearProjection.getEvaluations().stream()
                        .anyMatch(evaluation -> evaluation.getStatus() == GearStatus.UNCONFIRMED));
            }
            else
            {
                assertNotNull("Profile " + (char) ('A' + profile) + " needs a gear direction",
                    gearProjection.getRecommended());
            }
            assertTrue(journey.getCurrent().getTotalCount() > 0);
        }
    }

    private static AccountState stateAt(int level, BankSnapshot bank)
    {
        AccountState.Builder state = AccountState.builder().accountMode(AccountMode.IRONMAN).bank(bank);
        String[] skills = {"Attack", "Strength", "Defence", "Ranged", "Prayer", "Magic", "Runecraft",
            "Construction", "Hitpoints", "Agility", "Herblore", "Thieving", "Crafting", "Fletching",
            "Slayer", "Hunter", "Mining", "Smithing", "Fishing", "Cooking", "Firemaking", "Woodcutting",
            "Farming", "Sailing"};
        for (String skill : skills) state.skill(skill, level);
        return state.build();
    }

    private static void completeFirst(Route route, InMemoryManualOverrideStore overrides, int count)
    {
        int marked = 0;
        for (RouteSection section : route.getSections())
        {
            for (RouteStep step : section.getSteps())
            {
                if (marked++ >= count) return;
                overrides.put(step.getId(), ManualOverride.FORCE_COMPLETE);
            }
        }
    }
}

package com.ironcompass.gear;

import com.google.gson.Gson;
import java.io.StringReader;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class GearCatalogValidationTest
{
    @Test
    public void bundledCatalogHasFortyReviewedObjectives() throws Exception
    {
        GearCatalog catalog = new GearLoader(new Gson()).loadResource("/gear/ironman-gear-2026.json");
        new GearValidator().validate(catalog);
        assertEquals(40, catalog.getUpgrades().size());
        assertEquals("2026-08-27", catalog.getAuditedAt());
    }

    @Test(expected = GearValidationException.class)
    public void prerequisiteCyclesAreRejected() throws Exception
    {
        String json = "{\"version\":1,\"upgrades\":["
            + upgrade("a", "b") + "," + upgrade("b", "a") + "]}";
        GearCatalog catalog = new GearLoader(new Gson()).load(new StringReader(json), "cycle");
        new GearValidator().validate(catalog);
    }

    @Test(expected = GearValidationException.class)
    public void selfReferencesAreRejected() throws Exception
    {
        GearCatalog catalog = load("{\"version\":1,\"upgrades\":[" + valid("a", 1,
            "\"alternativeIds\":[\"a\"]") + "]}");
        new GearValidator().validate(catalog);
    }

    @Test(expected = GearValidationException.class)
    public void previousTierRegressionsAreRejected() throws Exception
    {
        GearCatalog catalog = load("{\"version\":1,\"upgrades\":["
            + valid("later", 3, "") + "," + valid("earlier", 2,
            "\"previousIds\":[\"later\"]") + "]}");
        new GearValidator().validate(catalog);
    }

    @Test(expected = GearValidationException.class)
    public void alternativesCannotPointBackIntoDependencyPath() throws Exception
    {
        GearCatalog catalog = load("{\"version\":1,\"upgrades\":["
            + valid("base", 1, "\"alternativeIds\":[\"upgrade\"]") + ","
            + valid("upgrade", 2, "\"previousIds\":[\"base\"]") + "]}");
        new GearValidator().validate(catalog);
    }

    @Test(expected = GearValidationException.class)
    public void previousCyclesAreRejected() throws Exception
    {
        GearCatalog catalog = load("{\"version\":1,\"upgrades\":["
            + valid("a", 1, "\"previousIds\":[\"b\"]") + ","
            + valid("b", 2, "\"previousIds\":[\"a\"]") + "]}");
        new GearValidator().validate(catalog);
    }

    @Test(expected = GearValidationException.class)
    public void invalidConditionTypesAreRejected() throws Exception
    {
        GearCatalog catalog = load("{\"version\":1,\"upgrades\":[{\"id\":\"gear.valid\","
            + "\"name\":\"Valid\",\"styles\":[\"MELEE\"],\"tier\":1,"
            + "\"completion\":{\"type\":\"UNKNOWN_FUTURE_TYPE\"}}]}");
        new GearValidator().validate(catalog);
    }

    @Test(expected = GearValidationException.class)
    public void persistenceSeparatorsAreRejectedInIds() throws Exception
    {
        GearCatalog catalog = load("{\"version\":1,\"upgrades\":[" + valid("gear:bad", 1, "") + "]}");
        new GearValidator().validate(catalog);
    }

    private static GearCatalog load(String json) throws Exception
    {
        return new GearLoader(new Gson()).load(new StringReader(json), "test");
    }

    private static String valid(String id, int tier, String relation)
    {
        String suffix = relation.isEmpty() ? "" : "," + relation;
        return "{\"id\":\"" + id + "\",\"name\":\"" + id + "\",\"styles\":[\"MELEE\"],"
            + "\"tier\":" + tier + ",\"completion\":{\"type\":\"ITEM_PRESENT\",\"itemId\":1}" + suffix + "}";
    }

    private static String upgrade(String id, String prerequisite)
    {
        return "{\"id\":\"" + id + "\",\"name\":\"" + id + "\",\"styles\":[\"MELEE\"],"
            + "\"tier\":1,"
            + "\"prerequisiteIds\":[\"" + prerequisite + "\"],"
            + "\"completion\":{\"type\":\"ITEM_PRESENT\",\"itemId\":1}}";
    }
}

