package com.ironcompass.requirement;

import com.google.gson.Gson;
import com.ironcompass.state.AccountState;
import com.ironcompass.state.BankSnapshot;
import com.ironcompass.state.QuestProgress;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class ConditionEvaluatorTest
{
    private final Gson gson = new Gson();
    private final ConditionEvaluator evaluator = new ConditionEvaluator();

    @Test
    public void skillAboveRequirementIsComplete()
    {
        AccountState state = AccountState.builder().skill("Magic", 52).build();
        assertEquals(TruthValue.TRUE, evaluator.evaluate(condition(
            "{\"type\":\"SKILL_AT_LEAST\",\"skill\":\"Magic\",\"level\":37}"), state).getValue());
    }

    @Test
    public void finishedQuestIsComplete()
    {
        AccountState state = AccountState.builder().quest("Waterfall Quest", QuestProgress.FINISHED).build();
        assertEquals(TruthValue.TRUE, evaluator.evaluate(condition(
            "{\"type\":\"QUEST_STATE\",\"quest\":\"Waterfall Quest\",\"state\":\"FINISHED\"}"), state).getValue());
    }

    @Test
    public void questHelperVarpMilestoneCompletesAtOrPastBoundary()
    {
        ConditionSpec milestone = condition(
            "{\"type\":\"VARP_AT_LEAST\",\"id\":71,\"value\":2}");

        assertEquals(TruthValue.FALSE, evaluator.evaluate(milestone,
            AccountState.builder().varp(71, 1).build()).getValue());
        assertEquals(TruthValue.TRUE, evaluator.evaluate(milestone,
            AccountState.builder().varp(71, 2).build()).getValue());
        assertEquals(TruthValue.TRUE, evaluator.evaluate(milestone,
            AccountState.builder().varp(71, 3).build()).getValue());
    }

    @Test
    public void unknownBankNeverBecomesMissing()
    {
        ConditionSpec rope = condition("{\"type\":\"ITEM_QUANTITY\",\"label\":\"Rope\",\"itemId\":954,\"quantity\":1,\"source\":\"ANY\"}");
        AccountState unknown = AccountState.builder().bank(BankSnapshot.unknown()).build();
        AccountState knownEmpty = AccountState.builder().bank(BankSnapshot.observed(Map.of())).build();

        assertEquals(TruthValue.UNKNOWN, evaluator.evaluate(rope, unknown).getValue());
        assertEquals(TruthValue.FALSE, evaluator.evaluate(rope, knownEmpty).getValue());
    }

    @Test
    public void allAndAnyPropagateThreeValuedLogic()
    {
        AccountState state = AccountState.builder().skill("Magic", 52).bank(BankSnapshot.unknown()).build();
        ConditionSpec all = condition("{\"type\":\"ALL\",\"children\":["
            + "{\"type\":\"SKILL_AT_LEAST\",\"skill\":\"Magic\",\"level\":37},"
            + "{\"type\":\"ITEM_PRESENT\",\"itemId\":954,\"source\":\"BANK\"}]}");
        ConditionSpec any = condition("{\"type\":\"ANY\",\"children\":["
            + "{\"type\":\"SKILL_AT_LEAST\",\"skill\":\"Magic\",\"level\":37},"
            + "{\"type\":\"ITEM_PRESENT\",\"itemId\":954,\"source\":\"BANK\"}]}");

        assertEquals(TruthValue.UNKNOWN, evaluator.evaluate(all, state).getValue());
        assertEquals(TruthValue.TRUE, evaluator.evaluate(any, state).getValue());
    }

    @Test
    public void itemAnyAcceptsEquivalentChargedVariationAndPreservesUnknownBank()
    {
        ConditionSpec gloryFamily = condition(
            "{\"type\":\"ITEM_ANY\",\"label\":\"Glory family\",\"source\":\"ANY\",\"itemIds\":[1704,6585]}");

        AccountState chargedGlory = AccountState.builder().inventoryItem(1712, 1).build();
        AccountState unknown = AccountState.builder().bank(BankSnapshot.unknown()).build();
        AccountState knownEmpty = AccountState.builder().bank(BankSnapshot.observed(Map.of())).build();

        assertEquals(TruthValue.TRUE, evaluator.evaluate(gloryFamily, chargedGlory).getValue());
        assertEquals(TruthValue.UNKNOWN, evaluator.evaluate(gloryFamily, unknown).getValue());
        assertEquals(TruthValue.FALSE, evaluator.evaluate(gloryFamily, knownEmpty).getValue());
    }

    @Test
    public void skillSumSupportsWarriorsGuildEntryRule()
    {
        ConditionSpec entry = condition("{\"type\":\"ANY\",\"children\":["
            + "{\"type\":\"SKILL_SUM_AT_LEAST\",\"skills\":[\"Attack\",\"Strength\"],\"level\":130},"
            + "{\"type\":\"SKILL_AT_LEAST\",\"skill\":\"Attack\",\"level\":99},"
            + "{\"type\":\"SKILL_AT_LEAST\",\"skill\":\"Strength\",\"level\":99}]}");

        assertEquals(TruthValue.TRUE, evaluator.evaluate(entry,
            AccountState.builder().skill("Attack", 65).skill("Strength", 65).build()).getValue());
        assertEquals(TruthValue.TRUE, evaluator.evaluate(entry,
            AccountState.builder().skill("Attack", 70).skill("Strength", 60).build()).getValue());
        assertEquals(TruthValue.TRUE, evaluator.evaluate(entry,
            AccountState.builder().skill("Attack", 99).skill("Strength", 1).build()).getValue());
        assertEquals(TruthValue.TRUE, evaluator.evaluate(entry,
            AccountState.builder().skill("Attack", 1).skill("Strength", 99).build()).getValue());
        assertEquals(TruthValue.FALSE, evaluator.evaluate(entry,
            AccountState.builder().skill("Attack", 60).skill("Strength", 60).build()).getValue());
    }

    @Test
    public void exactItemFamilyDoesNotCollapseImbuedAndUnimbuedSlayerHelmets()
    {
        ConditionSpec imbued = condition("{\"type\":\"ITEM_ANY_EXACT\",\"source\":\"ANY\","
            + "\"itemIds\":[11865,19641,25177,26674]}");

        assertEquals(TruthValue.FALSE, evaluator.evaluate(imbued,
            AccountState.builder().inventoryItem(11864, 1).bank(BankSnapshot.observed(Map.of())).build()).getValue());
        assertEquals(TruthValue.FALSE, evaluator.evaluate(imbued,
            AccountState.builder().inventoryItem(8921, 1).bank(BankSnapshot.observed(Map.of())).build()).getValue());
        assertEquals(TruthValue.TRUE, evaluator.evaluate(imbued,
            AccountState.builder().equipmentItem(11865, 1).build()).getValue());
        assertEquals(TruthValue.TRUE, evaluator.evaluate(imbued,
            AccountState.builder().bank(BankSnapshot.observed(Map.of(19641, 1))).build()).getValue());
    }

    private ConditionSpec condition(String json)
    {
        return gson.fromJson(json, ConditionSpec.class);
    }
}

package com.ironcompass.route;

import com.google.gson.Gson;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import net.runelite.api.Quest;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class RouteDataValidationTest
{
    @Test
    public void bundledRouteIsCompleteAndValid() throws Exception
    {
        Route route = new RouteLoader(new Gson()).loadResource("/routes/efficient-ironman.json");
        Set<String> questNames = Arrays.stream(Quest.values()).map(Quest::getName).collect(Collectors.toSet());
        new RouteValidator(questNames).validate(route);

        long steps = route.getSections().stream().flatMap(section -> section.getSteps().stream()).count();
        long training = route.getSections().stream().flatMap(section -> section.getSteps().stream())
            .filter(step -> step.getType() == StepType.TRAIN).count();
        assertEquals(341, steps);
        assertEquals(111, training);
        assertEquals(12, route.getChapters().size());
        assertTrue(hasTitle(route, "Learning the Ropes"));
        assertTrue(hasTitle(route, "Nature Spirit"));
        assertTrue(hasTitle(route, "Death Plateau"));
        assertTrue(hasTitle(route, "The Blood Moon Rises"));
        assertTrue(hasTitle(route, "The Corsair Curse"));

        RouteStep pirateMilestone = findStep(route, "Partial completion of Pirate's Treasure");
        assertEquals("VARP_AT_LEAST", pirateMilestone.getCompletion().getType());
        assertEquals(71, pirateMilestone.getCompletion().getId());
        assertEquals(2, pirateMilestone.getCompletion().getValue());
        assertEquals("Pirate's Treasure", pirateMilestone.getQuestHelperKey());
        assertTrue(new RouteVariables(route).getVarps().contains(71));
        assertTrue(hasTitle(route, "Demon Slayer — collect all three keys"));
        assertTrue(hasTitle(route, "Enter the Abyss — charge the scrying orb"));
        assertTrue(hasTitle(route, "Dwarf Cannon — repair the railings"));
        assertTrue(hasTitle(route, "Fairytale II — unlock fairy rings"));
    }

    @Test
    public void everyPublicRouteFileParsesAndValidates() throws Exception
    {
        Path directory = Paths.get("src", "main", "resources", "routes");
        List<Path> routeFiles;
        try (Stream<Path> files = Files.list(directory))
        {
            routeFiles = files.filter(path -> path.getFileName().toString().endsWith(".json"))
                .collect(Collectors.toList());
        }
        assertTrue("Expected at least one public route JSON file", !routeFiles.isEmpty());

        Set<String> questNames = Arrays.stream(Quest.values()).map(Quest::getName).collect(Collectors.toSet());
        for (Path routeFile : routeFiles)
        {
            try (InputStream input = Files.newInputStream(routeFile);
                 InputStreamReader reader = new InputStreamReader(input, StandardCharsets.UTF_8))
            {
                Route route = new RouteLoader(new Gson()).load(reader, routeFile.toString());
                new RouteValidator(questNames).validate(route);
            }
        }
    }

    @Test
    public void gearRoadmapHasCoreAndOptionalModernMilestones() throws Exception
    {
        Route gear = new RouteLoader(new Gson()).loadResource("/routes/gear-roadmap.json");
        new RouteValidator().validate(gear);

        List<RouteStep> steps = gear.getSections().stream()
            .flatMap(section -> section.getSteps().stream())
            .collect(Collectors.toList());
        assertEquals(46, steps.size());
        assertEquals(25, steps.stream().filter(step -> !step.isOptional()).count());
        assertEquals(21, steps.stream().filter(RouteStep::isOptional).count());
        assertTrue(hasTitle(gear, "Zombie axe bridge"));
        assertTrue(hasTitle(gear, "Bowfa and Crystal armour branch"));
        assertTrue(hasTitle(gear, "Twinflame staff from Royal Titans"));
        assertTrue(hasTitle(gear, "Doom of Mokhaiotl upgrades"));
        assertTrue(hasTitle(gear, "Soulflame horn"));
    }

    private boolean hasTitle(Route route, String title)
    {
        return route.getSections().stream().flatMap(section -> section.getSteps().stream())
            .anyMatch(step -> title.equals(step.getTitle()));
    }

    private RouteStep findStep(Route route, String title)
    {
        return route.getSections().stream().flatMap(section -> section.getSteps().stream())
            .filter(step -> title.equals(step.getTitle()))
            .findFirst()
            .orElseThrow(() -> new AssertionError("Missing route step: " + title));
    }
}

package com.ironcompass.route;

import com.google.gson.Gson;
import com.ironcompass.persistence.InMemoryManualOverrideStore;
import com.ironcompass.persistence.ManualOverride;
import com.ironcompass.requirement.ConditionEvaluator;
import com.ironcompass.state.AccountMode;
import com.ironcompass.state.AccountState;
import com.ironcompass.state.QuestProgress;
import java.io.StringReader;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class RouteEvaluatorTest
{
    private final RouteEvaluator evaluator = new RouteEvaluator(new ConditionEvaluator());

    @Test
    public void freshIronmanGetsFirstUnsatisfiedStep() throws Exception
    {
        RouteProjection projection = evaluate(basicRoute(), AccountState.builder()
            .accountMode(AccountMode.IRONMAN).skill("Magic", 1).build(), new InMemoryManualOverrideStore(), false);
        assertEquals("train-magic", projection.getCurrent().getStep().getId());
    }

    @Test
    public void existingAccountSkipsSatisfiedTrainingAndQuest() throws Exception
    {
        AccountState state = AccountState.builder().accountMode(AccountMode.IRONMAN).skill("Magic", 52)
            .quest("Waterfall Quest", QuestProgress.FINISHED).build();
        RouteProjection projection = evaluate(basicRoute(), state, new InMemoryManualOverrideStore(), false);
        assertEquals("next-goal", projection.getCurrent().getStep().getId());
        assertEquals(2, projection.getCompleteCount());
    }

    @Test
    public void manualSkipAndUnskipAdvancePredictably() throws Exception
    {
        InMemoryManualOverrideStore overrides = new InMemoryManualOverrideStore();
        AccountState state = AccountState.builder().skill("Magic", 1).build();
        Route route = basicRoute();
        overrides.put("train-magic", ManualOverride.SKIPPED);
        assertEquals("waterfall", evaluate(route, state, overrides, false).getCurrent().getStep().getId());
        overrides.remove("train-magic");
        assertEquals("train-magic", evaluate(route, state, overrides, false).getCurrent().getStep().getId());
    }

    @Test
    public void stableIdsPreserveOverridesAcrossInsertedRouteStep() throws Exception
    {
        InMemoryManualOverrideStore overrides = new InMemoryManualOverrideStore();
        overrides.put("waterfall", ManualOverride.FORCE_COMPLETE);
        AccountState state = AccountState.builder().skill("Magic", 52).build();
        Route changed = route("{\"routeId\":\"test\",\"version\":2,\"name\":\"Test\",\"sections\":[{\"id\":\"s\",\"name\":\"S\",\"steps\":["
            + manual("inserted", "Inserted") + "," + quest("waterfall", "Waterfall Quest") + "]}]}");
        RouteProjection projection = evaluate(changed, state, overrides, false);
        StepEvaluation waterfall = projection.getSteps().stream()
            .filter(step -> "waterfall".equals(step.getStep().getId())).findFirst().orElse(null);
        assertNotNull(waterfall);
        assertEquals(StepStatus.COMPLETE, waterfall.getStatus());
    }

    @Test
    public void hcimUsesOnlyExplicitSafeAlternative() throws Exception
    {
        Route route = route("{\"routeId\":\"hc\",\"version\":1,\"name\":\"HC\",\"sections\":[{\"id\":\"s\",\"name\":\"S\",\"steps\":["
            + "{\"id\":\"wild\",\"type\":\"ACTIVITY\",\"title\":\"Wild route\",\"instruction\":\"Go\",\"reason\":\"Fast\",\"risk\":\"WILDERNESS\",\"hcimAlternativeStepId\":\"safe\",\"completion\":{\"type\":\"MANUAL_ONLY\"}},"
            + "{\"id\":\"safe\",\"alternativeForStepId\":\"wild\",\"type\":\"ACTIVITY\",\"title\":\"Safe route\",\"instruction\":\"Go safely\",\"reason\":\"Safe\",\"completion\":{\"type\":\"MANUAL_ONLY\"}}"
            + "]}]}");
        AccountState hardcore = AccountState.builder().accountMode(AccountMode.HARDCORE_IRONMAN).build();
        AccountState standard = AccountState.builder().accountMode(AccountMode.IRONMAN).build();
        assertEquals("safe", evaluate(route, hardcore, new InMemoryManualOverrideStore(), true).getCurrent().getStep().getId());
        assertEquals("wild", evaluate(route, standard, new InMemoryManualOverrideStore(), true).getCurrent().getStep().getId());
    }

    private Route basicRoute() throws Exception
    {
        return route("{\"routeId\":\"test\",\"version\":1,\"name\":\"Test\",\"sections\":[{\"id\":\"s\",\"name\":\"S\",\"steps\":["
            + "{\"id\":\"train-magic\",\"type\":\"TRAIN\",\"title\":\"Train Magic\",\"instruction\":\"Train\",\"reason\":\"Requirement\",\"completion\":{\"type\":\"SKILL_AT_LEAST\",\"skill\":\"Magic\",\"level\":37}},"
            + quest("waterfall", "Waterfall Quest") + "," + manual("next-goal", "Next Goal") + "]}]}");
    }

    private String quest(String id, String title)
    {
        return "{\"id\":\"" + id + "\",\"type\":\"QUEST\",\"title\":\"" + title
            + "\",\"instruction\":\"Complete it\",\"reason\":\"Progress\",\"completion\":{\"type\":\"QUEST_STATE\",\"quest\":\"" + title + "\",\"state\":\"FINISHED\"}}";
    }

    private String manual(String id, String title)
    {
        return "{\"id\":\"" + id + "\",\"type\":\"MANUAL\",\"title\":\"" + title
            + "\",\"instruction\":\"Do it\",\"reason\":\"Progress\",\"completion\":{\"type\":\"MANUAL_ONLY\"}}";
    }

    private Route route(String json) throws Exception
    {
        return new RouteLoader(new Gson()).load(new StringReader(json), "test");
    }

    private RouteProjection evaluate(Route route, AccountState state, InMemoryManualOverrideStore overrides, boolean safe)
    {
        return evaluator.evaluate(route, state, overrides, safe, 4, 7);
    }
}

